import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-contact',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h1>Liên Hệ</h1><p>Chúng tôi luôn sẵn sàng hỗ trợ bạn</p></div></div>
    <section class="section">
      <div class="container">
        <div class="contact-layout">
          <div class="contact-info">
            <h2>Thông Tin Liên Hệ</h2>
            <div class="info-item"><span class="material-icons">location_on</span><div><h4>Địa chỉ</h4><p>Hà Nội, Việt Nam</p></div></div>
            <div class="info-item"><span class="material-icons">phone</span><div><h4>Điện thoại</h4><p>0901 234 567</p></div></div>
            <div class="info-item"><span class="material-icons">email</span><div><h4>Email</h4><p>info&#64;dulichquangba.vn</p></div></div>
            <div class="info-item"><span class="material-icons">schedule</span><div><h4>Giờ làm việc</h4><p>Thứ 2 - Thứ 6: 8:00 - 18:00</p></div></div>
          </div>
          <div class="contact-form-wrapper">
            <h2>Gửi Yêu Cầu</h2>
            <form (ngSubmit)="submit()">
              <div class="grid grid-2">
                <div class="form-group"><label>Họ tên *</label><input type="text" class="form-control" [(ngModel)]="form.name" name="name" required></div>
                <div class="form-group"><label>Email *</label><input type="email" class="form-control" [(ngModel)]="form.email" name="email" required></div>
              </div>
              <div class="grid grid-2">
                <div class="form-group"><label>Điện thoại</label><input type="tel" class="form-control" [(ngModel)]="form.phone" name="phone"></div>
                <div class="form-group"><label>Loại yêu cầu</label>
                  <select class="form-control" [(ngModel)]="form.type" name="type">
                    <option value="contact">Liên hệ chung</option>
                    <option value="tour">Tư vấn tour</option>
                    <option value="destination">Hỏi về địa điểm</option>
                  </select>
                </div>
              </div>
              <div class="form-group"><label>Tiêu đề *</label><input type="text" class="form-control" [(ngModel)]="form.subject" name="subject" required></div>
              <div class="form-group"><label>Nội dung *</label><textarea class="form-control" [(ngModel)]="form.message" name="message" rows="5" required></textarea></div>
              <div class="form-error" *ngIf="error">{{ error }}</div>
              <div class="form-success" *ngIf="success">Gửi yêu cầu thành công! Chúng tôi sẽ liên hệ sớm.</div>
              <button type="submit" class="btn btn-primary btn-lg" [disabled]="loading">
                <span class="material-icons">send</span> {{ loading ? 'Đang gửi...' : 'Gửi yêu cầu' }}
              </button>
            </form>
          </div>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .contact-layout { display: grid; grid-template-columns: 1fr 1.5fr; gap: 3rem; @media(max-width:768px){grid-template-columns:1fr;} }
    .contact-info { h2 { margin-bottom: 1.5rem; } }
    .info-item { display: flex; gap: 1rem; margin-bottom: 1.5rem; .material-icons { color: var(--primary); font-size: 1.5rem; margin-top: 0.25rem; } h4 { margin: 0 0 0.25rem; font-size: 1rem; } p { margin: 0; color: var(--gray); } }
    .contact-form-wrapper { h2 { margin-bottom: 1.5rem; } }
    .form-success { color: var(--secondary); font-weight: 600; padding: 0.75rem; background: rgba(25,135,84,0.1); border-radius: 8px; margin-bottom: 1rem; }
  `]
})
export class ContactComponent {
  form: any = { type: 'contact' };
  error = '';
  success = false;
  loading = false;

  constructor(private api: ApiService, public auth: AuthService) {
    if (this.auth.isLoggedIn()) {
      this.form.name = this.auth.user()?.fullName;
      this.form.email = this.auth.user()?.email;
    }
  }

  submit() {
    if (!this.form.name || !this.form.email || !this.form.subject || !this.form.message) {
      this.error = 'Vui lòng điền đầy đủ thông tin bắt buộc';
      return;
    }
    this.loading = true;
    this.error = '';
    this.api.createInquiry(this.form).subscribe({
      next: () => { this.success = true; this.loading = false; this.form = { type: 'contact' }; },
      error: (err) => { this.error = err.error?.error || 'Gửi thất bại'; this.loading = false; }
    });
  }
}
